package com.smartmerchant.saas.member.interfaces;
import com.smartmerchant.saas.member.application.MemberBenefitService;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.FORBIDDEN;
@RestController @RequestMapping("/internal/v1/member") public class MemberInternalController {private final MemberBenefitService service;private final String key;public MemberInternalController(MemberBenefitService service,@Value("${saas.security.internal-signing-key}") String key){this.service=service;this.key=key;}private void check(String provided){if(!key.equals(provided))throw new ResponseStatusException(FORBIDDEN,"Invalid internal key");}@PostMapping("/benefits/quote") public Object quote(@RequestHeader("X-Internal-Key")String k,@RequestBody MemberBenefitService.BenefitRequest r){check(k);return service.quote(r);}@PostMapping("/benefits/freeze") public Object freeze(@RequestHeader("X-Internal-Key")String k,@RequestBody MemberBenefitService.BenefitRequest r){check(k);return service.freeze(r);}@PostMapping("/benefits/confirm") public void confirm(@RequestHeader("X-Internal-Key")String k,@RequestBody MemberBenefitService.BenefitRequest r){check(k);service.confirm(r);}@PostMapping("/benefits/release") public void release(@RequestHeader("X-Internal-Key")String k,@RequestBody MemberBenefitService.BenefitRequest r){check(k);service.release(r);}@PostMapping("/benefits/refund") public void refund(@RequestHeader("X-Internal-Key")String k,@RequestBody MemberBenefitService.BenefitRequest r){check(k);service.refund(r);}}
